<script>
(() => {
 const entrada=document.getElementById('entrada'),sala=document.getElementById('sala'),form=document.getElementById('formEntrada'),erro=document.getElementById('erroEntrada'),configuracao=document.getElementById('configuracaoLiveKit'),verConfiguracao=document.getElementById('verConfiguracao'),palco=document.getElementById('palco'),miniaturas=document.getElementById('miniaturas'),status=document.getElementById('statusSala'),direcao=document.getElementById('direcao'),painelMidia=document.getElementById('painelMidia'),csrf='{{ csrf_token() }}',urlMidia='{{ route('transmissoes.midia', ['transmissao' => $transmissao->hash_publico]) }}';
 const nomeGuardado=@json($nomeSala);if(nomeGuardado)document.getElementById('nome').value=nomeGuardado;
 const botaoCorrigir=document.createElement('button');botaoCorrigir.id='corrigirImagem';botaoCorrigir.type='button';botaoCorrigir.className='btn btn-outline-light';botaoCorrigir.title='Espelhar ou corrigir a imagem da sua câmera';botaoCorrigir.innerHTML='<i class="bi bi-arrow-left-right me-1"></i>Corrigir imagem';document.getElementById('sair').before(botaoCorrigir);
 const botoes={camera:document.getElementById('camera'),microfone:document.getElementById('microfone'),tela:document.getElementById('tela'),corrigirImagem:document.getElementById('corrigirImagem'),sair:document.getElementById('sair')};let room,camera=true,microfone=true,tela=false,imagemCorrigida=false,administrador=false,arrastando=null;const tracks=new Map(),estado={layout:'camera-tela',cameras:[],apresentacao:null,ordem:[],fundo:'',sobreposicoes:[]};
 const fonte=p=>String(p.source||'').toLowerCase(),chave=(p,publicacao)=>`${p.identity}|${fonte(publicacao)}`,nome=p=>p.name||'Participante',eTela=p=>fonte(p).includes('screen'),eCamera=p=>fonte(p).includes('camera'),eMicrofone=p=>fonte(p).includes('microphone');
 const mostrarErro=(texto,exibirConfiguracao=false)=>{erro.textContent=texto;erro.classList.remove('d-none');verConfiguracao.classList.toggle('d-none',!exibirConfiguracao)};
 function botao(texto,classe,acao,desabilitado=false){const b=document.createElement('button');b.type='button';b.className=`btn btn-sm ${classe}`;b.textContent=texto;b.disabled=desabilitado;b.addEventListener('click',acao);return b}
 function video(track,mudo=false){const el=track.attach();el.autoplay=true;el.playsInline=true;el.muted=mudo;return el}
 function itemPalco(registro){const item=document.createElement('div'),id=`${registro.participante.identity}-${eTela(registro.publicacao)?'tela':'camera'}`.replace(/[^a-zA-Z0-9_-]/g,'_');item.className='palco-item';item.style.viewTransitionName=`palco_${id}`;const imagem=video(registro.track,registro.local);if(registro.local&&eCamera(registro.publicacao)&&imagemCorrigida)imagem.classList.add('video-corrigida');item.append(imagem);const rotulo=document.createElement('span');rotulo.className='palco-item__nome';rotulo.textContent=`${nome(registro.participante)}${eTela(registro.publicacao)?' — apresentação':''}`;item.append(rotulo);return item}
 function registroDe(identity,tipo){return [...tracks.values()].find(r=>r.participante.identity===identity && (tipo==='camera'?eCamera(r.publicacao):eTela(r.publicacao)) && !r.publicacao.isMuted)}
 function vazioPalco(texto){return Object.assign(document.createElement('div'),{className:'palco-vazio',textContent:texto})}
 function renderizarPalco(){palco.replaceChildren();palco.className='palco';const cameras=estado.cameras.map(id=>registroDe(id,'camera')).filter(Boolean),apresentacao=estado.apresentacao&&registroDe(estado.apresentacao,'tela'),layout=estado.layout;if(['participante','participante-cheio'].includes(layout)){palco.append(cameras[0]?itemPalco(cameras[0]):vazioPalco('Selecione um participante com câmera para o palco.'));return}if(layout==='dois-horizontal'){palco.classList.add('palco--dois-horizontal');for(let i=0;i<2;i++)palco.append(cameras[i]?itemPalco(cameras[i]):vazioPalco('Selecione participante'));return}if(layout==='tela'){palco.append(apresentacao?itemPalco(apresentacao):vazioPalco('Selecione uma apresentação'));return}if(layout==='tela-sobreposta'){palco.classList.add('palco--tela-sobreposta');palco.append(apresentacao?itemPalco(apresentacao):vazioPalco('Selecione uma apresentação'));if(cameras[0]){const sobreposto=itemPalco(cameras[0]);sobreposto.classList.add('palco-item--sobreposto');palco.append(sobreposto)}return}const tres=layout==='tres-cameras-tela';palco.classList.add(tres?'palco--tres-cameras-tela':'palco--camera-tela');const coluna=document.createElement('div');coluna.className=`palco-coluna${tres?' palco-coluna--tres':''}`;if(cameras.length)cameras.slice(0,tres?3:1).forEach(r=>coluna.append(itemPalco(r)));else coluna.append(vazioPalco('Selecione participante'));palco.append(coluna);palco.append(apresentacao?itemPalco(apresentacao):vazioPalco('Selecione uma apresentação'));}
 function alternar(lista,identidade,maximo){const i=lista.indexOf(identidade);if(i>=0)lista.splice(i,1);else{lista.push(identidade);if(lista.length>maximo)lista.splice(0,lista.length-maximo)}}
 async function alterarMudo(registro){const mudo=!registro.publicacao.isMuted;try{const resposta=await fetch(urlMidia,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({identity:registro.participante.identity,track_sid:registro.publicacao.trackSid||registro.publicacao.sid,muted:mudo})}),dados=await resposta.json();if(!resposta.ok)throw new Error(dados.message||'Não foi possível alterar a mídia.');status.textContent=mudo?`${nome(registro.participante)} foi silenciado.`:`${nome(registro.participante)} teve a mídia reativada.`}catch(ex){status.textContent=ex.message}}
 function maximoPalco(){return estado.layout==='dois-horizontal'?2:estado.layout==='tres-cameras-tela'?3:1}
 function renderizarMiniaturas(){miniaturas.replaceChildren();const pessoas=new Map(),cards=[];let apresentacaoLocal=null;for(const r of tracks.values()){if(!pessoas.has(r.participante.identity))pessoas.set(r.participante.identity,{participante:r.participante,local:r.local,camera:null,tela:null,microfone:null});const p=pessoas.get(r.participante.identity);if(eCamera(r.publicacao))p.camera=r;if(eTela(r.publicacao))p.tela=r;if(eMicrofone(r.publicacao))p.microfone=r}for(const p of pessoas.values()){if(p.camera||!p.tela)cards.push(criarMiniatura(p,p.camera,'camera'));if(p.tela){if(p.local)apresentacaoLocal={p,registro:p.tela};else cards.push(criarMiniatura(p,p.tela,'apresentação'))}}cards.sort((a,b)=>{const ai=estado.ordem.indexOf(a.dataset.card),bi=estado.ordem.indexOf(b.dataset.card);return(ai<0?9999:ai)-(bi<0?9999:bi)});cards.unshift(criarCardCompartilhar(apresentacaoLocal));cards.forEach(card=>miniaturas.append(card))}
 function criarCardCompartilhar(apresentacao){const card=document.createElement('article');card.className='participante';card.dataset.card='compartilhar';const preview=document.createElement('div');preview.className='participante-preview';if(apresentacao?.registro&&!apresentacao.registro.publicacao.isMuted)preview.append(video(apresentacao.registro.track,true));else preview.append(Object.assign(document.createElement('div'),{className:'participante-preview__vazio',innerHTML:'<i class="bi bi-display fs-3"></i>'}));card.append(preview);const titulo=document.createElement('div');titulo.className='participante-nome';titulo.textContent=apresentacao?'Sua apresentação':'Compartilhar apresentação';card.append(titulo);const acoes=document.createElement('div');acoes.className='participante-acoes';acoes.append(botao(tela?'Parar compartilhamento':'Compartilhar','btn-outline-primary',alternarTela));card.append(acoes);return card}
 function criarMiniatura(p,registro,tipo){const card=document.createElement('article'),identidade=p.participante.identity,chaveCard=`${identidade}|${tipo}`,cameraNoPalco=estado.cameras.includes(identidade)&&estado.layout!=='tela';card.className='participante';card.dataset.card=chaveCard;card.draggable=true;if(tipo==='camera'&&!cameraNoPalco)card.classList.add('participante--fora');const preview=document.createElement('div');preview.className='participante-preview';if(registro&&!registro.publicacao.isMuted)preview.append(video(registro.track,p.local));else preview.append(Object.assign(document.createElement('div'),{className:'participante-preview__vazio',textContent:tipo==='camera'?'Câmera desligada':'Apresentação indisponível'}));if(administrador&&tipo==='camera'){const topo=document.createElement('div');topo.className='participante-topo';if(!p.local&&p.microfone){const mic=botao('', 'btn-outline-light',()=>alterarMudo(p.microfone));mic.title=p.microfone.publicacao.isMuted?'Ativar microfone':'Desativar microfone';mic.setAttribute('aria-label',mic.title);mic.innerHTML=`<i class="bi bi-mic${p.microfone.publicacao.isMuted?'-mute':''}"></i>`;topo.append(mic)}const menu=document.createElement('details');menu.className='participante-menu';const resumo=document.createElement('summary');resumo.className='btn btn-outline-light btn-sm';resumo.title='Opções do participante';resumo.innerHTML='<i class="bi bi-three-dots-vertical"></i>';menu.append(resumo);const itens=document.createElement('div');itens.className='participante-menu__itens';const noPalco=estado.cameras.includes(identidade);itens.append(botao(noPalco?'Remover do palco':'Adicionar ao palco','',()=>{alternar(estado.cameras,identidade,maximoPalco());renderizar()}));if(!p.local&&registro)itens.append(botao(registro.publicacao.isMuted?'Ativar câmera':'Desativar câmera','',()=>alterarMudo(registro)));menu.append(itens);topo.append(menu);preview.append(topo)}card.append(preview);const titulo=document.createElement('div');titulo.className='participante-nome';titulo.textContent=`${nome(p.participante)}${tipo==='apresentação'?' — apresentação':''}`;card.append(titulo);const acoes=document.createElement('div');acoes.className='participante-acoes';if(administrador&&tipo==='apresentação'){const visivel=estado.apresentacao===identidade;acoes.append(botao(visivel?'Ocultar do palco':'Mostrar no palco',visivel?'btn-primary':'btn-outline-light',()=>{estado.apresentacao=visivel?null:identidade;renderizar()}))}else if(!administrador)acoes.append(Object.assign(document.createElement('small'),{className:'text-white-50',textContent:p.local?'Você':'Aguardando direção'}));card.append(acoes);card.addEventListener('dragstart',()=>{arrastando=chaveCard;card.classList.add('participante--arrastando')});card.addEventListener('dragend',()=>{arrastando=null;card.classList.remove('participante--arrastando')});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();if(!arrastando||arrastando===chaveCard)return;const ordem=estado.ordem.filter(k=>k!==arrastando&&k!==chaveCard),indice=ordem.indexOf(chaveCard);ordem.splice(indice<0?ordem.length:indice,0,arrastando);estado.ordem=ordem;renderizar()});return card}
 function aplicarMidias(){palco.classList.toggle('palco--tem-fundo',!!estado.fundo);if(estado.fundo){const fundo=document.createElement('div');fundo.className='palco-fundo';fundo.style.backgroundImage=`url("${estado.fundo}")`;palco.prepend(fundo)}const camada=document.createElement('div');camada.className='palco-midia';estado.sobreposicoes.forEach(m=>{const item=document.createElement('div');item.className='palco-midia__item';item.style.left=m.x+'%';item.style.top=m.y+'%';item.style.width=m.largura+'%';const imagem=document.createElement('img');imagem.src=m.url;imagem.alt='';imagem.addEventListener('error',()=>{status.textContent='Não foi possível carregar uma imagem da Biblioteca.'});item.append(imagem);item.addEventListener('pointerdown',e=>{if(e.button!==0)return;const inicio={x:e.clientX,y:e.clientY,esquerda:m.x,topo:m.y},retangulo=palco.getBoundingClientRect();item.setPointerCapture(e.pointerId);const mover=ev=>{m.x=Math.max(0,Math.min(95,inicio.esquerda+(ev.clientX-inicio.x)/retangulo.width*100));m.y=Math.max(0,Math.min(95,inicio.topo+(ev.clientY-inicio.y)/retangulo.height*100));item.style.left=m.x+'%';item.style.top=m.y+'%'};item.addEventListener('pointermove',mover);item.addEventListener('pointerup',()=>item.removeEventListener('pointermove',mover),{once:true})});camada.append(item)});palco.append(camada)}
 function renderizar(){for(const r of tracks.values())if(r.track.kind==='video')r.track.detach();renderizarPalco();aplicarMidias();renderizarMiniaturas();document.querySelectorAll('[data-layout]').forEach(b=>b.classList.toggle('active',b.dataset.layout===estado.layout))}
 function renderizarComTransicao(){if(document.startViewTransition){document.startViewTransition(()=>renderizar());return}renderizar();palco.classList.remove('palco--animando');void palco.offsetWidth;palco.classList.add('palco--animando')}
 function registrar(track,publicacao,participante,local=false){tracks.set(chave(participante,publicacao),{track,publicacao,participante,local});if(track.kind==='audio'){if(!local){const a=track.attach();a.autoplay=true;document.getElementById('audioRemoto').append(a)}renderizar();return}if(track.kind!=='video')return;renderizar()}
 function remover(publicacao,participante){tracks.delete(chave(participante,publicacao));renderizar()}
 function atualizarControles(){botoes.camera.innerHTML=`<i class="bi bi-camera-video${camera?'':'-off'} me-1"></i>${camera?'Desligar câmera':'Ligar câmera'}`;botoes.microfone.innerHTML=`<i class="bi bi-mic${microfone?'':'-mute'} me-1"></i>${microfone?'Silenciar':'Ligar microfone'}`;botoes.tela.innerHTML=`<i class="bi bi-display me-1"></i>${tela?'Parar compartilhamento':'Compartilhar tela'}`}
 async function alternarTela(){try{tela=!tela;await room.localParticipant.setScreenShareEnabled(tela);atualizarControles();renderizar()}catch(ex){tela=false;atualizarControles();status.textContent='Não foi possível compartilhar a tela: '+ex.message}}
 function iniciarMidias(){if(!painelMidia||painelMidia.dataset.iniciado)return;painelMidia.dataset.iniciado='1';const formatar=item=>{if(!item.id)return item.text;const miniatura=item.element.dataset.miniatura;return $('<span class="midia-opcao"><img alt=""><span></span></span>').find('img').attr('src',miniatura).end().find('span').text(item.text).end()};$('.midia-select').select2({theme:'bootstrap-5',width:'100%',templateResult:formatar,templateSelection:formatar,escapeMarkup:m=>m});$('#fundoPalco').on('change',function(){estado.fundo=this.value;renderizar()});$('#sobreposicaoPalco').on('change',function(){if(!this.value)return;estado.sobreposicoes.push({url:this.value,x:8+estado.sobreposicoes.length*4,y:8+estado.sobreposicoes.length*4,largura:18});this.value='';$(this).trigger('change.select2');renderizar()})}
 new MutationObserver(()=>{if(administrador&&!sala.classList.contains('d-none')){painelMidia?.classList.remove('d-none');iniciarMidias()}}).observe(sala,{attributes:true,attributeFilter:['class']});
 botoes.corrigirImagem.addEventListener('click',()=>{imagemCorrigida=!imagemCorrigida;botoes.corrigirImagem.classList.toggle('btn-primary',imagemCorrigida);botoes.corrigirImagem.classList.toggle('btn-outline-light',!imagemCorrigida);botoes.corrigirImagem.setAttribute('aria-pressed',String(imagemCorrigida));renderizar()});
 async function entrar(nomeEntrada){const resposta=await fetch('{{ route('transmissoes.entrar', ['transmissao' => $transmissao->hash_publico]) }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({nome:nomeEntrada})}),dados=await resposta.json();if(!resposta.ok)throw Object.assign(new Error(dados.message||'Não foi possível entrar na sala.'),{configuracao:!!dados.configuracao});administrador=!!dados.administrador;direcao.classList.toggle('d-none',!administrador);room=new LivekitClient.Room();room.on(LivekitClient.RoomEvent.TrackSubscribed,(t,p,u)=>registrar(t,p,u));room.on(LivekitClient.RoomEvent.TrackUnsubscribed,remover);room.on(LivekitClient.RoomEvent.TrackPublished,(p,u)=>{if(p.track)registrar(p.track,p,u)});room.on(LivekitClient.RoomEvent.TrackMuted,()=>renderizar());room.on(LivekitClient.RoomEvent.TrackUnmuted,()=>renderizar());room.on(LivekitClient.RoomEvent.ParticipantDisconnected,p=>{for(const [k,r] of tracks)if(r.participante.identity===p.identity)tracks.delete(k);estado.cameras=estado.cameras.filter(id=>id!==p.identity);if(estado.apresentacao===p.identity)estado.apresentacao=null;renderizar()});room.on(LivekitClient.RoomEvent.Disconnected,()=>{status.textContent='Você saiu da sala.'});await room.connect(dados.url,dados.token);await room.localParticipant.setCameraEnabled(true);await room.localParticipant.setMicrophoneEnabled(true);room.localParticipant.trackPublications.forEach(p=>{if(p.track)registrar(p.track,p,room.localParticipant,true)});status.textContent=administrador?'Conectado como administrador do palco.':'Conectado. Sua câmera e seu microfone estão ativos.';entrada.classList.add('d-none');sala.classList.remove('d-none');atualizarControles();renderizar()}
 form.addEventListener('submit',async e=>{e.preventDefault();erro.classList.add('d-none');const b=form.querySelector('button[type="submit"]');b.disabled=true;try{await entrar(document.getElementById('nome').value.trim())}catch(ex){mostrarErro(ex.message,ex.configuracao);b.disabled=false}});verConfiguracao.addEventListener('click',()=>{const oculto=configuracao.classList.toggle('d-none');verConfiguracao.textContent=oculto?'Ver configuração':'Ocultar configuração';verConfiguracao.setAttribute('aria-expanded',String(!oculto))});document.querySelectorAll('[data-layout]').forEach(b=>b.addEventListener('click',()=>{estado.layout=b.dataset.layout;estado.cameras=estado.cameras.slice(0,maximoPalco());renderizarComTransicao()}));botoes.camera.addEventListener('click',async()=>{camera=!camera;await room.localParticipant.setCameraEnabled(camera);atualizarControles()});botoes.microfone.addEventListener('click',async()=>{microfone=!microfone;await room.localParticipant.setMicrophoneEnabled(microfone);atualizarControles()});botoes.tela.addEventListener('click',alternarTela);botoes.sair.addEventListener('click',()=>{room?.disconnect();tracks.clear();sala.classList.add('d-none');entrada.classList.remove('d-none')});
})();
</script>
@endpush
